import type { KeywordDef } from '../types';

/**
 * Glossaire officiel des mots-clés de Star Wars: Legion (2e édition), tel
 * que fourni par l'utilisateur depuis le livret de règles.
 *
 * Réorganisé et reconstruit à partir d'un texte extrait de PDF (mise en page
 * 2 colonnes) : quelques paragraphes coupés par des sauts de page ont été
 * recollés à la bonne entrée. En cas de doute, vérifiez toujours le livret
 * officiel. Chaque entrée reste modifiable depuis l'appli (bouton
 * « Modifier ») et vos corrections sont sauvegardées localement.
 */

const UNIT_KEYWORDS: KeywordDef[] = [
  { id: 'accomplir-la-mission', name: 'Accomplir la Mission', hasValue: false, category: 'unité', definition: "Pendant la mise en place, pour chaque unité dotée du mot-clé Accomplir la Mission, placez un pion Mission prioritaire (pion Avantage) allié sur le champ de bataille, en territoire contesté. Tant qu'une unité dotée du mot-clé Accomplir la Mission se trouve à 1 d'un ou plusieurs pions Mission prioritaire alliés, cette unité gagne Adrénaline : Dodge. Lorsqu'une unité dotée du mot-clé Accomplir la Mission attaque une unité ennemie à 1 d'un ou plusieurs pions Mission prioritaire alliés, la réserve d'attaque de l'unité attaquante gagne le mot-clé Critique 2." },
  { id: 'agile', name: 'Agile', hasValue: false, category: 'unité', definition: "Après qu'une unité dotée du mot-clé Agile a défendu contre une attaque, si elle a dépensé au moins un pion Esquive à n'importe quel moment de la séquence d'attaque, elle gagne un pion Esquive." },
  { id: 'aguerri', name: 'Aguerri', hasValue: false, category: 'unité', definition: "Après qu'une unité dotée du mot-clé Aguerri a effectué au cours de son activation une action Se déplacer, elle peut effectuer une action Attaquer gratuite. Pendant cette action Attaquer, elle ne peut ajouter que des armes à distance aux réserves d'attaques." },
  { id: 'aide', name: "Aide : Affiliation/Type d'Unité", hasValue: false, category: 'unité', definition: "Chaque fois qu'une unité dotée du mot-clé Aide est censée gagner un pion Viser, Esquive ou Adrénaline, une autre unité alliée de l'affiliation ou du type spécifié à 2 et en LdV peut gagner ce pion à la place. Dans ce cas, l'unité dotée du mot-clé Aide gagne un pion Suppression, si possible. Par exemple, Logray gagne 2 pions Viser et 1 pion Esquive au début de son activation, grâce à son amélioration Ingrédients Secrets. Il décide d'utiliser son mot-clé Aide et une unité de Tirailleurs Ewok gagne 1 de ces pions Viser, et une unité de Frondeurs Ewok gagne l'autre pion Viser. Logray gagne 1 pion Suppression pour chaque utilisation de son mot-clé Aide. Au total il gagne donc 2 pions Suppression et 1 pion Esquive de ses Ingrédients Secrets." },
  { id: 'allies-de-circonstance', name: 'Alliés de Circonstance', hasValue: false, category: 'unité', definition: "Les unités dotées du mot-clé Alliés de Circonstance peuvent donner des ordres à des unités de mercenaires alliées de n'importe quelle affiliation. De plus, lors de la création d'armée, les joueurs peuvent inclure une unité de mercenaires supplémentaire dans leur armée sans prendre en compte son rang si au moins une unité dotée du mot-clé Alliés de Circonstance est présente. Ils ne peuvent cependant pas inclure plus d'unités d'un rang particulier que ce qui est normalement autorisé." },
  { id: 'alourdissement', name: 'Alourdissement', hasValue: false, category: 'unité', definition: "Tant qu'une unité dotée du mot-clé Alourdissement possède un pion Objectif revendiqué, elle ne peut pas utiliser le mot-clé Saut." },
  { id: 'assistance-x', name: 'Assistance X', hasValue: true, category: 'unité', definition: "En tant qu'action de carte, une unité dotée du mot-clé Assistance X peut choisir jusqu'à X unités alliées à 2 : elles gagnent un pion Adrénaline chacune." },
  { id: 'associe', name: "Associé : Nom d'Unité", hasValue: false, category: 'unité', definition: "Pendant la création d'armée, une unité dotée du mot-clé Associé ne compte pas dans le nombre maximal d'unités de son rang pouvant être incluses si une unité portant le nom spécifié est incluse dans la même armée." },
  { id: 'attaque-impetueuse', name: 'Attaque Impétueuse', hasValue: false, category: 'unité', definition: 'Au début de son activation, une unité dotée du mot-clé Attaque Impétueuse peut augmenter ou diminuer sa vitesse maximale de 1 jusqu\'à la fin de cette activation.' },
  { id: 'autodestruction-x-unite', name: 'Autodestruction X (unité)', hasValue: true, category: 'unité', definition: "Une unité ne peut effectuer une action de carte Autodestruction X que si elle a un nombre de pions Blessure supérieur ou égal à la moitié de son seuil de blessure, arrondi au supérieur. Pour chaque unité à 1 et en LdV, lancez X dés d'attaque noirs, en résolvant entièrement chaque jet avant de passer à l'unité suivante. L'unité visée subit 1 blessure pour chaque résultat Touche et Critique obtenu, puis elle gagne 1 pion Suppression pour chaque résultat Succès obtenu. Une fois que tous les jets sont résolus, l'unité ayant utilisé l'action de carte est vaincue." },
  { id: 'autonome', name: 'Autonome : Pion X/Action', hasValue: true, category: 'unité', definition: "Au début de la Phase d'Activation, si une unité dotée du mot-clé Autonome ne possède pas de pion Ordre, cette unité peut gagner X pions spécifiés ou effectuer l'action spécifiée en tant qu'action gratuite." },
  { id: 'barrage', name: 'Barrage', hasValue: false, category: 'unité', definition: "Une unité dotée du mot-clé Barrage peut effectuer deux actions Attaquer au lieu d'une si elle n'utilise pas le mot-clé Arsenal au cours de son activation." },
  { id: 'blessure-x', name: 'Blessure X', hasValue: true, category: 'unité', definition: "La première fois qu'une unité dotée du mot-clé Blessure X entre en jeu, cette unité subit X blessures." },
  { id: 'blocage', name: 'Blocage', hasValue: false, category: 'unité', definition: "Lorsqu'une unité dotée du mot-clé Blocage défend, si elle dépense un ou plusieurs pions Esquive au cours de l'étape « Appliquer les esquives et couverts », elle gagne Adrénaline : Dodge." },
  { id: 'bouclier-x', name: 'Bouclier X', hasValue: true, category: 'unité', definition: "Une unité dotée du mot-clé Bouclier X possède X pions Bouclier. Les pions Bouclier appartiennent à l'unité et ne sont pas attribués individuellement à des figurines. Si une unité gagne le mot-clé Bouclier X, elle gagne X pions Bouclier. De même, si une unité perd le mot-clé Bouclier X, elle perd X pions Bouclier. Les pions Bouclier sont recto verso : un côté actif et un côté inactif. Ils entrent toujours en jeu côté actif visible. Lorsqu'une unité retourne un pion Bouclier actif, ce pion devient inactif (le côté inactif du pion est désormais visible). Lorsqu'une unité retourne un pion Bouclier inactif, ce pion devient actif (le côté actif du pion est désormais visible). Tant qu'elle défend contre une attaque à distance, pendant l'étape « Modifier les dés d'attaque », une unité en défense peut retourner n'importe quel nombre de ses pions Bouclier actifs sur leur côté inactif afin d'annuler un résultat Succès ou Critique par pion Bouclier ainsi retourné." },
  { id: 'cache', name: 'Cache', hasValue: false, category: 'unité', definition: "Pendant la mise en place, une unité équipée d'une carte Amélioration dotée du mot-clé Cache place le ou les pions indiqués sur la carte où figure le mot-clé Cache. L'unité peut dépenser ces pions, même si une ou plusieurs des figurines ajoutées à l'unité grâce à cette carte sont vaincues." },
  { id: 'calcul-de-probabilites', name: 'Calcul de Probabilités', hasValue: false, category: 'unité', definition: "En tant qu'action de carte, une unité dotée du mot-clé Calcul de Probabilités peut choisir une unité de soldats alliée à 2 et en LdV : cette dernière gagne un pion Viser, un pion Esquive et un pion Suppression." },
  { id: 'charge', name: 'Charge', hasValue: false, category: 'unité', definition: "Après qu'une unité dotée du mot-clé Charge a effectué, au cours de son activation, une action Se déplacer qui l'amène au contact d'une figurine ennemie afin d'attaquer au corps-à-corps, cette unité peut effectuer une action Attaquer gratuite contre cette unité en n'utilisant que des armes de corps-à-corps." },
  { id: 'chasseur-de-jedi', name: 'Chasseur de Jedi', hasValue: false, category: 'unité', definition: "Lorsqu'une unité dotée du mot-clé Chasseur de Jedi attaque une unité dont la barre d'amélioration affiche une icône d'amélioration Force, elle gagne Critique : Blast." },
  { id: 'ciblage-avance', name: "Ciblage Avancé : Type d'Unité X", hasValue: true, category: 'unité', definition: "Lorsqu'une unité dotée du mot-clé Ciblage Avancé X effectue une attaque contre une unité ennemie du type spécifié, pendant l'étape « Constituer la réserve d'attaque », elle peut gagner X pions Viser. Une unité qui utilise le mot-clé Ciblage Avancé X ne peut constituer qu'une réserve d'attaque et saute l'étape « Déclarer un défenseur supplémentaire » de la séquence d'attaque." },
  { id: 'cible-x', name: 'Cible X', hasValue: true, category: 'unité', definition: "Après qu'une unité dotée du mot-clé Cible X a reçu un ordre, elle gagne X pions Viser." },
  { id: 'commandant-des-operations', name: 'Commandant des Opérations', hasValue: false, category: 'unité', definition: "Pendant la création d'armée, une armée incluant une unité dotée du mot-clé Commandant des Opérations peut ignorer le nombre minimal de rangs Commandement autorisés. Si l'armée d'un joueur ne contient pas d'unité Commandement pendant la mise en place, mais qu'elle contient une unité dotée du mot-clé Commandant des Opérations, cette unité gagne un pion Commandant. Lorsqu'un joueur révèle une carte Commandement non spécifique à un Commandant ou Opérative nommé, il peut nommer une unité alliée dotée du mot-clé Commandant des Opérations comme Commandant, lui permettant ainsi de donner des ordres. Une unité dotée du mot-clé Commandant des Opérations n'est pas un Commandant et n'est considérée comme tel que pour donner des ordres avec une carte Commandement au cours de la Phase de Commandement. Une unité dotée du mot-clé Commandant des Opérations est considérée comme un Commandant de cette faction ou affiliation lorsque vous créez votre main de commandement. De plus, si une unité alliée se trouve à 3 de l'unité possédant le pion Commandement et que les deux unités appartiennent à la même faction ou affiliation, cette unité alliée peut considérer que l'unité dotée du mot-clé Commandant des Opérations est une unité Commandement ayant une valeur de Commandement de 2." },
  { id: 'conseils', name: "Conseils : Type d'Unité", hasValue: false, category: 'unité', definition: "Lorsqu'une unité utilise l'action de carte Conseils, choisissez une autre unité alliée du type spécifié et située à 2. L'unité choisie effectue une action gratuite autre qu'Attaquer." },
  { id: 'contrainte', name: 'Contrainte : Rang/Type d\'Unité', hasValue: false, category: 'unité', definition: "Après qu'une autre unité de soldats non-droïdes alliée correspondant au rang ou type indiqué située à 2 d'une unité alliée dotée du mot-clé Contrainte a effectué son étape « Se rallier », si elle est démoralisée mais pas paniquée, au début de son étape « Effectuer des actions », elle peut gagner un pion Suppression pour effectuer une action Se déplacer gratuite." },
  { id: 'coordination', name: "Coordination : Nom/Type d'Unité", hasValue: false, category: 'unité', definition: "Après qu'une unité dotée du mot-clé Coordination a reçu un ordre, elle peut donner un ordre à une unité alliée à 1 qui porte le nom ou est du type spécifié. Une unité pour laquelle sont spécifiés plusieurs noms ou types d'unités ne peut donner un ordre qu'à une seule de ces unités en utilisant le mot-clé Coordination. Si une unité déjà dotée du mot-clé Coordination gagne ce mot-clé une seconde fois, cette unité peut choisir à quelles cibles elle donne un ordre parmi les unités spécifiées sur les deux mots-clés : elle ne donne pas deux ordres." },
  { id: 'coup-de-chance-x', name: 'Coup de Chance X', hasValue: true, category: 'unité', definition: "Tant qu'une unité dotée du mot-clé Coup de Chance X défend contre une attaque, elle peut relancer jusqu'à X de ses dés de défense au cours de l'étape « Relancer les dés de défense ». Tous les dés relancés grâce au mot-clé Coup de Chance X doivent l'être en même temps, et chaque dé ne peut pas être relancé plus d'une fois." },
  { id: 'couvert-x', name: 'Couvert X', hasValue: true, category: 'unité', definition: "Une unité dotée du mot-clé Couvert X qui défend contre une attaque comportant au moins une arme à distance améliore, pendant l'étape « Appliquer les esquives et couverts », la valeur numérique de son couvert d'un nombre égal à X." },
  { id: 'defense-x', name: 'Défense X', hasValue: true, category: 'unité', definition: "Après qu'une unité dotée du mot-clé Défense X a reçu un ordre, elle gagne X pions Esquive." },
  { id: 'deflexion', name: 'Déflexion', hasValue: false, category: 'unité', definition: "Tant qu'une unité dotée du mot-clé Déflexion défend contre une attaque à distance ou utilise le mot-clé Gardien X, sa fenêtre de conversion d'adrénaline gagne Adrénaline : Dodge. De plus, pendant l'étape « Convertir les adrénalines de défense », avant de convertir les résultats Adrénaline, l'attaquant subit une blessure si le joueur a obtenu au moins un résultat Adrénaline dans son jet de défense. Quand une unité ayant le mot-clé Déflexion utilise le mot-clé Gardien X, avant de convertir des adrénalines de défense avec le mot-clé Maîtrise du Soresu, l'attaquant subit une blessure si au moins un des dés lancés par le mot-clé Gardien X a produit au moins un résultat Adrénaline. Si le mot-clé Déflexion permet de vaincre l'unité attaquante, l'attaque continue et le défenseur peut toujours subir des blessures. Tant qu'une unité défend ou utilise le mot-clé Gardien X contre une attaque dont la réserve d'attaque contient uniquement des armes dotées du mot-clé Haute Vélocité, le mot-clé Déflexion n'a pas d'effet." },
  { id: 'demoraliser-x', name: 'Démoraliser X', hasValue: true, category: 'unité', definition: "Après qu'une unité dotée du mot-clé Démoraliser X a effectué son étape « Se rallier », ajoutez jusqu'à X pions Suppression à des unités ennemies à 2." },
  { id: 'detachement', name: "Détachement : Nom/Type d'Unité", hasValue: false, category: 'unité', definition: "Pendant la création d'armée, une unité dotée du mot-clé Détachement ne compte pas dans le nombre maximal d'unités de son rang pouvant être incluses. Une unité dotée du mot-clé Détachement ne peut être incluse dans l'armée d'un joueur que si une autre unité qui porte le nom ou est du type spécifié, et qui n'est pas dotée du mot-clé Détachement, est également incluse dans cette armée. Chaque unité dotée du mot-clé Détachement doit être associée à sa propre unité spécifiée. De plus, pendant l'étape « Se déployer sur les positions préparées », une unité dotée du mot-clé Détachement gagne le mot-clé Infiltration ou Position Préparée jusqu'à la fin de la partie si l'unité spécifiée correspondante est dotée de ce mot-clé. Par exemple, une joueuse souhaite ajouter un Soldat avec Mortier DF-90 à son armée. Comme le Soldat avec Mortier DF-90 est doté du mot-clé Détachement : Shoretroopers, la joueuse doit ajouter une unité de Shoretroopers à son armée avant d'ajouter le Soldat avec Mortier DF-90. La joueuse s'exécute, son armée contient donc désormais une unité de Shoretroopers et une unité de Soldat avec Mortier DF-90. La joueuse souhaite ensuite ajouter une seconde unité de Soldat avec Mortier DF-90 à son armée : elle doit donc d'abord sélectionner une seconde unité de Shoretroopers à inclure dans son armée." },
  { id: 'discipline-x', name: 'Discipliné X', hasValue: true, category: 'unité', definition: "Après qu'une unité dotée du mot-clé Discipliné X a reçu un ordre, elle peut retirer jusqu'à X pions Suppression." },
  { id: 'discret', name: 'Discret', hasValue: false, category: 'unité', definition: "Tant qu'une unité dotée du mot-clé Discret possède au moins un pion Suppression, lorsqu'une unité ennemie effectue une attaque, elle doit cibler une autre unité, si possible. Lorsqu'une unité dotée du mot-clé Discret se rallie, elle peut choisir de ne pas retirer un nombre de pions Suppression de son choix, y compris zéro." },
  { id: 'distraire', name: 'Distraire', hasValue: false, category: 'unité', definition: "En tant qu'action de carte gratuite, une unité dotée du mot-clé Distraire peut choisir une unité de soldats ennemie à 2 et en LdV. Jusqu'à la fin du round, lorsque l'unité ennemie choisie effectue une attaque, elle doit attaquer l'unité qui a utilisé Distraire, si possible. Tant que l'unité ennemie choisie attaque l'unité dotée du mot-clé Distraire, chaque figurine de l'unité ennemie doit choisir une arme éligible afin de l'ajouter à une réserve d'attaque. L'unité ennemie peut déclarer des défenseurs supplémentaires et constituer des réserves de dés supplémentaires uniquement si, après avoir constitué une réserve de dés avec des armes éligibles, il reste des armes que des figurines de l'unité peuvent utiliser et qui n'étaient pas éligibles pour contribuer à la première réserve d'attaque. Lorsqu'une unité utilise le mot-clé Distraire, si elle était dotée du mot-clé Discret, elle le perd jusqu'à la fin du round." },
  { id: 'duelliste', name: 'Duelliste', hasValue: false, category: 'unité', definition: "Lorsqu'une unité dotée du mot-clé Duelliste effectue une attaque au corps-à-corps, si elle dépense un ou plusieurs pions Viser pendant l'étape « Relancer les dés d'attaque », la réserve d'attaque gagne le mot-clé d'arme Perforant 1. Tant qu'une unité dotée du mot-clé Duelliste défend contre une attaque au corps-à-corps, si elle dépense au moins un pion Esquive pendant l'étape « Appliquer les esquives et couverts », elle gagne le mot-clé Immunité : perforant. L'unité dotée du mot-clé Duelliste bénéficie de ces effets en plus des effets normaux déclenchés en utilisant des pions Viser et Esquive." },
  { id: 'eclaireur-x', name: 'Éclaireur X', hasValue: true, category: 'unité', definition: "Lorsqu'une unité non déployée dotée du mot-clé Éclaireur X s'active, au début de l'étape « Effectuer des actions », elle peut se déployer en effectuant une action Se déplacer à vitesse X gratuite, en ignorant le terrain difficile. Une unité peut effectuer ce déplacement quelle que soit sa vitesse maximale. Le mot-clé Éclaireur X peut se cumuler, mais pas au-dessus de 3. Si une unité est censée être dotée d'Éclaireur X au-dessus de 3, elle est dotée d'Éclaireur 3 à la place." },
  { id: 'equipe-declaireurs-x', name: "Équipe d'Éclaireurs X", hasValue: true, category: 'unité', definition: "Pendant la mise en place, le joueur contrôlant une unité dotée du mot-clé Équipe d'Éclaireurs X peut choisir jusqu'à X unités de soldats alliées appartenant à la même faction ou affiliation que cette unité et qui ne sont pas dotées du mot-clé Éclaireur. Chaque unité choisie gagne le mot-clé Éclaireur X jusqu'à la fin de la partie, X étant égal à la valeur d'Éclaireur X de l'unité dotée du mot-clé Équipe d'Éclaireurs X." },
  { id: 'enrage-x', name: 'Enragé X', hasValue: true, category: 'unité', definition: "Lorsqu'une unité dotée du mot-clé Enragé X possède un nombre de pions Blessure supérieur ou égal à X, cette unité gagne le mot-clé Charge. De plus, elle considère sa valeur de courage comme « - » et perd tout pion Suppression qu'elle possède. Si une unité dotée du mot-clé Enragé X possède un nombre de pions Blessure supérieur ou égal à X, mais qu'elle retire des pions Blessure grâce à un effet et se retrouve avec moins de pions Blessure que X, elle ne bénéficie plus du mot-clé Enragé X jusqu'à ce qu'elle ait de nouveau un nombre de pions Blessure supérieur ou égal à X." },
  { id: 'entourage', name: "Entourage : Nom d'Unité", hasValue: false, category: 'unité', definition: "Pendant la création d'armée, si un joueur inclut une unité dotée du mot-clé Entourage, une unité spécifiée par le mot-clé Entourage ne compte pas dans le nombre maximal d'unités de son rang pouvant être incluses. Un joueur peut donc inclure plus d'unités d'un rang spécifique qu'autorisé par les prérequis de rang. Lors de la Phase de Commandement, pendant l'étape « Nommer des Commandants et donner des ordres », une unité dotée du mot-clé Entourage peut donner un ordre à une unité alliée à 2 portant le nom spécifié par le mot-clé Entourage. De plus, l'unité spécifiée par le mot-clé Entourage ignore le prérequis de rang Commandement pour prêter main-forte à l'unité dotée du mot-clé Entourage. Par exemple, le Directeur Orson Krennic est doté du mot-clé Entourage : Death Troopers. Si une armée inclut le Directeur Orson Krennic, 1 unité de Death Troopers de la même armée ne compte pas dans le nombre maximal d'unités du rang forces spéciales autorisé dans l'armée, ce qui permet au joueur d'inclure jusqu'à trois autres unités de forces spéciales en plus des Death Troopers. Lors de la Phase de Commandement, le Directeur Orson Krennic peut donner un ordre à une unité de Death Troopers à 2." },
  { id: 'equipe', name: 'Équipe', hasValue: false, category: 'unité', definition: "Pendant la création d'armée, si un joueur inclut une unité dotée du mot-clé Équipe, cette unité doit s'équiper des améliorations spécifiées après le mot-clé." },
  { id: 'equipe-avec-arme-lourde', name: 'Équipe avec Arme Lourde', hasValue: false, category: 'unité', definition: "Une unité dotée du mot-clé Équipe avec Arme Lourde doit s'équiper d'une carte Amélioration Arme Lourde. La figurine ajoutée à l'unité grâce à cette carte Amélioration devient le Chef d'unité." },
  { id: 'exemplaire', name: 'Exemplaire', hasValue: false, category: 'unité', definition: "Tant qu'elle attaque ou défend, si une unité alliée se trouve à 2 et en LdV d'une ou plusieurs unités alliées dotées du mot-clé Exemplaire et qui appartiennent à la même faction ou affiliation que l'unité attaquante ou en défense, cette unité attaquante ou en défense peut dépenser un pion Viser, Esquive ou Adrénaline appartenant à une de ces unités dotées du mot-clé Exemplaire comme si cette unité attaquante ou en défense possédait le pion." },
  { id: 'escorte', name: "Escorte : Nom/Type d'Unité", hasValue: false, category: 'unité', definition: "Au début de la Phase d'Activation, si une unité dotée du mot-clé Escorte se trouve à 2 d'une autre unité ou type d'unité allié(e) spécifié(e) par le mot-clé Escorte, elle gagne soit un pion Viser, soit un pion Esquive. De plus, une unité dotée du mot-clé Escorte ignore le prérequis de rang Commandement pour prêter main-forte à l'unité spécifiée." },
  { id: 'fiable-x', name: 'Fiable X', hasValue: true, category: 'unité', definition: "Au début de la Phase d'Activation, une unité dotée du mot-clé Fiable X gagne X pions Adrénaline." },
  { id: 'fumee-x', name: 'Fumée X', hasValue: true, category: 'unité', definition: "Une unité dotée du mot-clé Fumée X peut effectuer l'action Fumée X. Pour effectuer cette action, l'unité place X pions Fumée intégralement à 1 et en LdV de son Chef d'unité. Les pions Fumée ne peuvent pas chevaucher les pions Objectif, Avantage et Charge, ni les autres pions Fumée, et ils doivent être placés sur une surface plane. Pions Fumée : les unités de soldats dont le Chef se trouve à 1 d'un pion Fumée améliorent de 1 la valeur numérique de leur couvert au cours de l'étape « Déterminer le couvert ». Tant qu'une unité de soldats attaque, si le Chef de l'unité attaquante se trouve à 1 d'un pion Fumée, l'unité en défense améliore de 1 la valeur numérique de son couvert. Les effets qui améliorent le couvert d'une unité peuvent se cumuler. Une unité ne peut pas être affectée par un même pion Fumée plus d'une fois. Les pions Fumée sont retirés pendant l'étape « Retirer les pions » de la Phase Finale. Par exemple, une unité de soldats dont le Chef d'unité se trouve à 1 de 2 pions Fumée améliore de 2 la valeur numérique de son couvert." },
  { id: 'gardien-x', name: 'Gardien X', hasValue: true, category: 'unité', definition: "Tant qu'une unité de soldats alliée à 1 et en ligne de vue d'une unité dotée du mot-clé Gardien X défend contre une attaque à distance, elle peut annuler jusqu'à X résultats Succès au cours de l'étape « Modifier les dés d'attaque » de la séquence d'attaque. Pour chaque Succès annulé de cette manière, l'unité dotée du mot-clé Gardien X lance un dé de défense correspondant à celui de sa carte Unité. Après avoir converti des résultats Adrénaline de défense en fonction de sa fenêtre d'adrénaline ou grâce à des pions Adrénaline, l'unité dotée du mot-clé Gardien X gagne 1 pion Suppression, puis subit 1 blessure pour chaque résultat vierge. Une unité en défense sur laquelle le mot-clé Gardien X est utilisé gagne un pion Suppression normalement. Une unité ne peut pas utiliser Gardien X si l'unité en défense est également dotée du mot-clé Gardien X. Si plusieurs unités alliées peuvent utiliser le mot-clé Gardien X au cours d'une attaque, le joueur qui contrôle ces unités déclare quelle unité utilise le mot-clé Gardien X et résout sa capacité avant de choisir s'il déclare qu'une autre unité utilise le mot-clé Gardien X. Une unité ne peut pas utiliser Gardien X si elle possède un nombre de pions Suppression supérieur ou égal à sa valeur de courage. Le mot-clé Perforant X peut être utilisé pour annuler des résultats Critique sur des dés de défense lancés par une unité utilisant Gardien X ; considérez les résultats Critique annulés comme des résultats vierges. Après une telle utilisation du mot-clé Perforant X, toute valeur de Perforant X non utilisée peut toujours être utilisée pour annuler des résultats Critique obtenus par l'unité en défense. De plus, une unité dotée du mot-clé Gardien X ne peut pas se faire prêter main-forte et ignore le prérequis de rang Commandement pour prêter main-forte." },
  { id: 'generateur-x', name: 'Générateur X', hasValue: true, category: 'unité', definition: "Pendant la Phase Finale, une unité dotée du mot-clé Générateur X peut retourner jusqu'à X pions Bouclier inactifs afin d'afficher leur côté actif." },
  { id: 'grimpeur-experimente', name: 'Grimpeur Expérimenté', hasValue: false, category: 'unité', definition: "Lorsqu'une unité dotée du mot-clé Grimpeur Expérimenté grimpe, elle peut parcourir une distance verticale allant jusqu'à 2 de hauteur." },
  { id: 'ia', name: 'IA : Action', hasValue: false, category: 'unité', definition: "Quand une unité dotée du mot-clé IA commence son étape « Effectuer des actions », si elle n'a pas de pion Ordre face visible et si 1 des conditions listées ci-dessous est remplie, elle doit effectuer 1 des actions spécifiées par son mot-clé IA. • L'unité est démoralisée mais pas paniquée. • L'unité possède un pion Dégât de véhicule. • C'est une unité de véhicule et au moins la moitié de ses figurines avec lesquelles elle a commencé la partie ont été vaincues. Si l'unité ne peut effectuer aucune des actions spécifiées par son mot-clé IA, elle effectue une action de moins lors de son étape « Effectuer des actions »." },
  { id: 'immunite-armes-portee-1', name: 'Immunité : Armes Portée 1', hasValue: false, category: 'unité', definition: "Une réserve d'attaque attribuée à une unité dotée du mot-clé Immunité : armes portée 1 ne peut pas contenir d'armes ayant une portée maximale de 1." },
  { id: 'immunite-corps-a-corps', name: 'Immunité : Corps-à-Corps', hasValue: false, category: 'unité', definition: "Les unités dotées du mot-clé Immunité : corps-à-corps ne peuvent pas être ciblées par des attaques au corps-à-corps et ne peuvent pas être engagées. Lorsqu'elle constitue une réserve d'attaque qui cible une unité ayant Immunité : corps-à-corps, l'unité attaquante peut ajouter des armes à distance à la réserve d'attaque, même si elle est au corps-à-corps avec l'unité en défense." },
  { id: 'immunite-deflagration', name: 'Immunité : Déflagration', hasValue: false, category: 'unité', definition: "Tant qu'une unité dotée du mot-clé Immunité : déflagration défend, les effets du mot-clé Déflagration sont ignorés." },
  { id: 'immunite-effets-ennemis', name: 'Immunité : Effets Ennemis', hasValue: false, category: 'unité', definition: "Une unité dotée du mot-clé Immunité : effets ennemis ignore tous les effets des cartes ennemies et ne peut pas être ciblée par les effets des cartes ennemies." },
  { id: 'immunite-perforant', name: 'Immunité : Perforant', hasValue: false, category: 'unité', definition: "Tant qu'une unité dotée du mot-clé Immunité : perforant défend, l'attaquant ne peut pas utiliser le mot-clé d'arme Perforant X pour annuler des résultats Critique des dés de défense pendant l'étape « Modifier les dés de défense ». Tant qu'une unité dotée du mot-clé Immunité : perforant utilise le mot-clé Gardien X, l'unité attaquante ne peut pas utiliser le mot-clé Perforant X pour annuler des résultats Critique obtenus sur les dés de défense lancés par cette unité pour le mot-clé Gardien X." },
  { id: 'immunite-perforant-corps-a-corps', name: 'Immunité : Perforant au Corps-à-Corps', hasValue: false, category: 'unité', definition: "Tant qu'une unité dotée du mot-clé Immunité : perforant au corps-à-corps défend contre une attaque au corps-à-corps, l'attaquant ne peut pas utiliser le mot-clé d'arme Perforant X pour annuler des résultats Critique des dés de défense pendant l'étape « Modifier les dés de défense ». Tant qu'une unité dotée du mot-clé Immunité : perforant au corps-à-corps utilise le mot-clé Gardien X au cours d'une attaque au corps-à-corps, l'unité attaquante ne peut pas utiliser le mot-clé Perforant X pour annuler des résultats Critique obtenus sur les dés de défense lancés par cette unité pour le mot-clé Gardien X." },
  { id: 'impitoyable', name: 'Impitoyable', hasValue: false, category: 'unité', definition: "Lorsqu'une autre unité de soldats alliée à 2 et en LdV qui possède un pion Ordre face visible s'active, elle peut subir 1 blessure pour effectuer 1 action gratuite." },
  { id: 'implacable', name: 'Implacable', hasValue: false, category: 'unité', definition: "Après qu'une unité dotée du mot-clé Implacable a effectué au cours de son activation une action Se Déplacer, elle peut effectuer une action Attaquer gratuite." },
  { id: 'inarretable', name: 'Inarrêtable', hasValue: false, category: 'unité', definition: "Une unité dotée du mot-clé Inarrêtable est éligible pour s'activer pendant la Phase d'Activation tant qu'elle possède au maximum 1 pion Ordre. Cette unité ne peut jamais posséder plus d'un pion Ordre face visible. Tant que cette unité n'est pas vaincue, lors de la constitution de sa réserve d'ordres, le joueur qui la contrôle ajoute à sa réserve d'ordres un pion Ordre supplémentaire correspondant au rang de cette unité." },
  { id: 'incognito', name: 'Incognito', hasValue: false, category: 'unité', definition: "Une unité dotée du mot-clé Incognito ne peut pas être attaquée par des unités ennemies se trouvant au-delà de 1 de cette dernière. De plus, elle ne peut pas contester d'objectifs, ni prêter main-forte. Si une unité dotée du mot-clé Incognito effectue une attaque ou défend contre une attaque, elle perd toutes les règles spéciales du mot-clé Incognito jusqu'à la fin de la partie. De plus, au début de l'activation d'une unité dotée du mot-clé Incognito, elle peut choisir de perdre les règles spéciales du mot-clé Incognito jusqu'à la fin de la partie." },
  { id: 'indifferent', name: 'Indifférent', hasValue: false, category: 'unité', definition: "Une unité dotée du mot-clé Indifférent ne peut pas bénéficier d'un couvert, et les figurines de cette unité ne peuvent être ni réparées ni restaurées." },
  { id: 'indomptable', name: 'Indomptable', hasValue: false, category: 'unité', definition: "Lorsqu'une unité dotée du mot-clé Indomptable effectue son étape « Se rallier », elle lance des dés de défense rouges à la place de dés de défense blancs." },
  { id: 'infanterie-mecanisee', name: 'Infanterie Mécanisée', hasValue: false, category: 'unité', definition: "Au début de la Phase d'Activation, chaque unité dotée du mot-clé Infanterie Mécanisée peut choisir une unité de véhicule alliée différente à 2. Dans ce cas, l'unité dotée du mot-clé Infanterie Mécanisée et chaque unité choisie gagnent 1 pion Viser ou 1 pion Esquive." },
  { id: 'infiltration', name: 'Infiltration', hasValue: false, category: 'unité', definition: "Au début de l'activation d'une unité non déployée dotée du mot-clé Infiltration, elle peut se déployer en plaçant son Chef d'unité intégralement en territoire allié. Ensuite, les autres figurines de cette unité sont placées en cohésion avec leur Chef d'unité et intégralement en territoire allié. Les figurines ne peuvent pas chevaucher le terrain infranchissable lorsqu'elles sont placées en utilisant le mot-clé Infiltration." },
  { id: 'influence-divine', name: 'Influence Divine', hasValue: false, category: 'unité', definition: "Tant qu'elles sont à 1 et en LdV d'un C-3PO allié, les autres unités de soldats alliées gagnent le mot-clé Gardien 2 : C-3PO. Tant qu'elles utilisent Gardien, elles peuvent annuler les résultats Critique comme s'il s'agissait de résultats Succès." },
  { id: 'insensible', name: 'Insensible', hasValue: false, category: 'unité', definition: "Quand une unité dotée du mot-clé Insensible devrait avoir 1 ou plusieurs résultats Critique annulés par le mot-clé Perforant X, annulez-en un de moins." },
  { id: 'inspiration-x', name: 'Inspiration X', hasValue: true, category: 'unité', definition: "À la fin de l'activation d'une unité dotée du mot-clé Inspiration X, retirez au total jusqu'à X pions Suppression d'autres unités alliées à 2." },
  { id: 'instinct-de-survie', name: 'Instinct de Survie', hasValue: false, category: 'unité', definition: "Lorsque vous vérifiez si une unité dotée du mot-clé Instinct de Survie panique, cette unité ne peut pas utiliser la valeur de courage des unités n'appartenant pas à la même affiliation." },
  { id: 'interrogatoire', name: 'Interrogatoire', hasValue: false, category: 'unité', definition: "Pendant la Phase de Commandement, si un joueur révèle une carte Commandement qui appartient à une unité se trouvant à 1 d'une ou plusieurs unités ennemies dotées du mot-clé Interrogatoire et que les joueurs sont à égalité pour la priorité, considérez cette carte Commandement comme affichant un point lumineux supplémentaire." },
  { id: 'intrepide', name: 'Intrépide', hasValue: false, category: 'unité', definition: "Après qu'une unité de soldats non-droïdes dotée du mot-clé Intrépide a effectué son étape « Se rallier », si elle est démoralisée mais pas paniquée, au début de son étape « Effectuer des actions », elle peut gagner un pion Suppression afin d'effectuer une action Se déplacer gratuite. Une unité dotée du mot-clé Intrépide ne peut pas être affectée par le mot-clé Contrainte." },
  { id: 'intuition-du-danger-x', name: 'Intuition du Danger X', hasValue: true, category: 'unité', definition: "Lorsqu'une unité dotée du mot-clé Intuition du Danger X est censée retirer n'importe quel nombre de ses pions Suppression, elle peut choisir de ne pas retirer jusqu'à X pions, y compris zéro. Tant qu'une unité dotée du mot-clé Intuition du Danger X défend contre une attaque, elle lance un dé de défense supplémentaire pendant l'étape « Lancer les dés de défense » pour chaque pion Suppression qu'elle possède, jusqu'à X dés supplémentaires." },
  { id: 'je-fais-aussi-partie-de-lequipe', name: "Je Fais Aussi Partie de l'Équipe", hasValue: false, category: 'unité', definition: "Une unité dotée du mot-clé Je Fais Aussi Partie de l'Équipe conteste un pion Objectif si son Chef d'unité se trouve à 1 de ce pion, au lieu de la distance normale." },
  { id: 'je-sens-le-profit', name: 'Je Sens le Profit', hasValue: false, category: 'unité', definition: "Lorsque la valeur X est présente dans les mots-clés ou statistiques d'une unité dotée du mot-clé Je Sens le Profit (sur sa carte Unité), X est égal au nombre de points lumineux figurant sur la carte Commandement que le joueur contrôlant cette unité a jouée et révélée le plus récemment lors de cette partie, jusqu'à un minimum de 1. Si le joueur n'a pas encore joué et révélé de carte Commandement, considérez X comme 1." },
  { id: 'la-mort-venue-du-ciel', name: 'La Mort Venue du Ciel', hasValue: false, category: 'unité', definition: "Lorsqu'une unité dotée du mot-clé La Mort Venue du Ciel attaque, l'unité en défense ne peut pas utiliser un couvert pour annuler les résultats Succès au cours de l'étape « Appliquer le couvert » si le Chef de l'unité attaquante chevauche un élément de terrain non en zone d'une hauteur supérieure à tout terrain que le Chef de l'unité en défense chevauche." },
  { id: 'la-victoire-ou-la-mort', name: 'La Victoire ou la Mort', hasValue: false, category: 'unité', definition: "Lorsqu'une unité alliée dotée du mot-clé La Victoire ou la Mort subit au moins 1 blessure d'une attaque ennemie, après la résolution de l'attaque, cette unité alliée peut gagner 1 pion Suppression. Dans ce cas, elle peut gagner 1 pion Viser ou 1 pion Esquive." },
  { id: 'les-mandaloriens-sont-plus-forts-ensemble', name: 'Les Mandaloriens sont Plus Forts Ensemble', hasValue: false, category: 'unité', definition: "Lorsqu'une unité alliée dotée du mot-clé Les Mandaloriens sont Plus Forts Ensemble dépense au moins 1 pion Viser, après que l'effet a été résolu, elle gagne 1 pion Esquive si elle est à 2 d'une autre unité alliée dotée du mot-clé Les Mandaloriens sont Plus Forts Ensemble. Lorsqu'une unité alliée dotée du mot-clé Les Mandaloriens sont Plus Forts Ensemble dépense au moins 1 pion Esquive, après que l'effet a été résolu, elle gagne 1 pion Viser si elle est à 2 d'une autre unité alliée dotée du mot-clé Les Mandaloriens sont Plus Forts Ensemble." },
  { id: 'longueur-davance', name: "Longueur d'Avance", hasValue: false, category: 'unité', definition: "Si une ou plusieurs unités alliées sont dotées du mot-clé Longueur d'avance, pendant l'étape Résoudre les cartes Commandement, après avoir révélé les cartes Commandement mais avant d'en résoudre les effets, si le nombre de points lumineux présents sur les cartes Commandement révélées ne correspond pas, 1 unité alliée dotée du mot-clé Longueur d'avance et se trouvant sur le champ de bataille peut effectuer un déplacement à vitesse 1. Si le nombre de points lumineux correspond, et qu'il y a 1 ou plusieurs unités alliées dotées du mot-clé Longueur d'avance sur le champ de bataille, choisissez une unité alliée se trouvant sur le champ de bataille. L'unité choisie peut effectuer un déplacement à vitesse 1." },
  { id: 'maitre-conteur', name: 'Maître Conteur', hasValue: false, category: 'unité', definition: "Lorsqu'une unité effectue l'action de carte Maître Conteur, elle choisit jusqu'à X unités alliées à 2, X étant égal au numéro du round en cours. Chaque unité choisie gagne 2 pions Adrénaline." },
  { id: 'maitre-de-la-force-x', name: 'Maître de la Force X', hasValue: true, category: 'unité', definition: "À la fin de son activation, une unité dotée du mot-clé Maître de la Force X peut redresser jusqu'à X de ses cartes Amélioration Force inclinées." },
  { id: 'maitrise-de-lataru', name: "Maîtrise de l'Ataru", hasValue: false, category: 'unité', definition: "Une unité dotée du mot-clé Maîtrise de l'Ataru peut effectuer jusqu'à deux actions Attaquer au cours de son activation. Lorsqu'elle attaque, elle gagne un pion Esquiver une fois que l'attaque est résolue. Lorsqu'elle défend, elle gagne un pion Viser une fois l'attaque résolue." },
  { id: 'maitrise-du-djem-so', name: 'Maîtrise du Djem So', hasValue: false, category: 'unité', definition: "Lorsqu'une unité dotée du mot-clé Maîtrise du Djem So défend contre une attaque au corps-à-corps, pendant l'étape « Comparer les résultats », l'unité attaquante subit une blessure si le jet d'attaque contient un ou plusieurs résultats vierges." },
  { id: 'maitrise-du-jarkai', name: "Maîtrise du Jar'Kai", hasValue: false, category: 'unité', definition: "Tant qu'elle effectue une attaque au corps-à-corps, une unité dotée du mot-clé Maîtrise du Jar'Kai peut, après avoir converti les adrénalines d'attaque au cours de l'étape « Convertir les adrénalines d'attaque », dépenser n'importe quel nombre de pions Esquive. Pour chaque pion Esquive ainsi dépensé, transformez un résultat vierge en un résultat Succès ou un résultat Succès en un résultat Critique, ou bien dépensez deux pions Esquive pour transformer un résultat vierge en résultat Critique." },
  { id: 'maitrise-du-juyo', name: 'Maîtrise du Juyo', hasValue: false, category: 'unité', definition: "Tant qu'une unité dotée du mot-clé Maîtrise du Juyo possède un ou plusieurs pions Blessure, elle peut effectuer une action supplémentaire pendant son activation. Une unité dotée du mot-clé Maîtrise du Juyo ne peut effectuer que deux actions Se déplacer pendant son activation, actions gratuites incluses." },
  { id: 'maitrise-du-makashi', name: 'Maîtrise du Makashi', hasValue: false, category: 'unité', definition: "Tant qu'une unité dotée du mot-clé Maîtrise du Makashi effectue une attaque au corps-à-corps, pendant l'étape « Choisir les armes et rassembler les dés », elle peut réduire de 1 la valeur de Perforant X d'une arme de la réserve d'attaque. Dans ce cas, le défenseur ne peut pas utiliser les mots-clés Immunité : perforant au corps-à-corps, Immunité : perforant et Insensible au cours de cette attaque." },
  { id: 'maitrise-du-shien', name: 'Maîtrise du Shien', hasValue: false, category: 'unité', definition: "Lorsqu'une unité dotée du mot-clé Maîtrise du Shien utilise le mot-clé Déflexion, l'attaquant subit 1 blessure pour chaque résultat Adrénaline du jet de défense à la place de toute autre blessure que le mot-clé Déflexion aurait dû provoquer. De plus, quand une unité dotée du mot-clé Maîtrise du Shien est l'unité en défense d'une attaque à distance, si elle ne subit pas de blessures lors de cette attaque, elle ne gagne pas de pion Suppression pendant l'étape « Attribuer un pion Suppression au défenseur » de cette attaque." },
  { id: 'maitrise-du-soresu', name: 'Maîtrise du Soresu', hasValue: false, category: 'unité', definition: "Lorsqu'une unité dotée du mot-clé Maîtrise du Soresu défend contre une attaque à distance, elle peut relancer tous ses dés de défense au cours de l'étape « Relancer les dés de défense ». De plus, lorsqu'une unité dotée du mot-clé Maîtrise du Soresu utilise le mot-clé Gardien X, elle peut dépenser un pion Esquive avant de convertir les résultats Adrénaline. Dans ce cas, elle relance tous ses dés de défense avant de convertir les résultats Adrénaline. Chaque dé ne peut pas être relancé plus d'une fois grâce à Maîtrise du Soresu." },
  { id: 'maitrise-du-vaapad', name: 'Maîtrise du Vaapad', hasValue: false, category: 'unité', definition: "Lorsqu'une unité dotée du mot-clé Maîtrise du Vaapad attaque, avant de lancer les dés, elle ajoute 1 dé d'attaque blanc à la réserve pour chaque pion Blessure qu'elle possède, pour un maximum de 3. Lorsqu'une unité dotée du mot-clé Maîtrise du Vaapad défend, avant de lancer les dés, elle ajoute 1 dé de défense blanc à la réserve pour chaque pion Blessure qu'elle possède, pour un maximum de 3." },
  { id: 'malin', name: 'Malin', hasValue: false, category: 'unité', definition: "Pendant la Phase de Commandement, si un joueur révèle une carte Commandement spécifique à un Commandant ou Opérative nommé dont l'unité est dotée du mot-clé Malin et que les joueurs sont à égalité pour la priorité, considérez cette carte Commandement comme affichant un point lumineux de moins, pour un minimum de 0. Si les deux joueurs révèlent une carte Commandement spécifique à un Commandant ou Opérative nommé dont l'unité est dotée du mot-clé Malin, l'égalité pour la priorité demeure." },
  { id: 'manoeuvre-improbable', name: 'Manœuvre Improbable', hasValue: false, category: 'unité', definition: "Pendant l'étape « Appliquer les esquives et couverts », une unité dotée du mot-clé Manœuvre Improbable peut dépenser des pions Esquive pour annuler des résultats Critique." },
  { id: 'marche-forcee', name: 'Marche Forcée', hasValue: false, category: 'unité', definition: "Lorsqu'une unité dotée du mot-clé Marche Forcée se déplace, son contrôleur peut lui attribuer un pion Suppression afin d'augmenter de 1 sa vitesse maximale pour ce déplacement, jusqu'à un maximum de 3. Lorsqu'une unité se déplace, appliquez tout effet qui augmente sa vitesse maximale avant d'appliquer les effets qui réduisent la vitesse maximale de cette unité. Par exemple, une unité ayant normalement une vitesse maximale de 1, mais qui possède 1 pion Immobilisation, peut utiliser le mot-clé Marche Forcée pour effectuer un déplacement d'une vitesse maximale totale de 1. Néanmoins, une unité ayant normalement une vitesse maximale de 1, mais qui possède 2 pions Immobilisation, ne peut pas utiliser le mot-clé Marche Forcée pour effectuer un déplacement car sa vitesse maximale sera alors égale à 0." },
  { id: 'matamore', name: 'Matamore', hasValue: false, category: 'unité', definition: "Lorsqu'une unité dotée du mot-clé Matamore dépense au moins 1 pion Viser lors d'une action Attaquer, après que l'effet a été résolu, elle gagne 1 pion Esquive." },
  { id: 'mercenaire', name: 'Mercenaire : Faction', hasValue: false, category: 'unité', definition: "Une unité dotée du mot-clé Mercenaire est une unité de mercenaire. La ou les factions spécifiées par le mot-clé Mercenaire peuvent inclure cette unité dans une armée en tant qu'unité de mercenaire." },
  { id: 'mettre-a-couvert-x', name: 'Mettre à Couvert X', hasValue: true, category: 'unité', definition: "En tant qu'action de carte, une unité dotée du mot-clé Mettre à Couvert X peut choisir jusqu'à X unités alliées à 2. Chaque unité choisie gagne un pion Esquive." },
  { id: 'mission-secrete', name: 'Mission Secrète', hasValue: false, category: 'unité', definition: "Au début de chaque Phase de Commandement, si une unité dotée du mot-clé Mission Secrète se trouve intégralement en territoire ennemi, elle gagne un pion Mission secrète. Une unité ne peut gagner qu'un seul pion Mission secrète lors de la partie. Au moment de marquer des PV, si un joueur contrôle une ou plusieurs unités ayant un pion Mission secrète et que ces unités se trouvent intégralement en territoire ennemi, ce joueur peut décider de retirer ces pions Mission secrète. Il marque 1 PV pour chaque pion Mission secrète ainsi retiré." },
  { id: 'mobile', name: 'Mobile', hasValue: false, category: 'unité', definition: "Lorsqu'une unité ayant un socle avec encoches dotée du mot-clé Mobile effectue un déplacement, elle saute l'étape 1 de la section « Déplacement des socles avec encoches », consistant à tourner le socle du Chef d'unité. Une unité dotée du mot-clé Mobile doit effectuer une action Se déplacer obligatoire gratuite au début ou à la fin de son étape « Effectuer des actions ». Une unité dotée du mot-clé Mobile ne peut pas reculer. Si une unité dotée du mot-clé Mobile effectue plusieurs actions Se déplacer non obligatoires au cours de son activation, elle ne peut pas revendiquer de pions Atout pendant cette activation. De plus, une unité dotée du mot-clé Mobile qui a revendiqué un pion Atout ne peut effectuer qu'une seule action Se déplacer non obligatoire pendant son activation." },
  { id: 'mobilite-difficile', name: 'Mobilité Difficile', hasValue: false, category: 'unité', definition: "Pendant son activation, une unité dotée du mot-clé Mobilité Difficile ne peut effectuer qu'une action Se déplacer." },
  { id: 'mode-roue', name: 'Mode Roue', hasValue: false, category: 'unité', definition: "Au début de son activation, une unité dotée du mot-clé Mode Roue peut changer sa vitesse pour être à vitesse 3 jusqu'à la fin de cette activation. Dans ce cas, jusqu'à la fin du round, elle perd le mot-clé Indifférent, gagne les mots-clés IA : Déplacement et Couvert 2, et ne peut pas retourner ses pions Bouclier actifs. Pour indiquer qu'une unité de Droïdekas utilise le Mode Roue, un joueur peut remplacer ses figurines de Droïdekas debout par des figurines de Droïdekas en roue, ou placer à côté de l'unité un pion Mode Roue. Les joueurs ne doivent utiliser les figurines de Droïdekas en roue que lorsque l'unité utilise le mot-clé Mode Roue et uniquement jusqu'à la fin du round : les figurines de Droïdekas en roue doivent alors toutes être remplacées par des figurines debout." },
  { id: 'nous-nous-battons-pour-notre-famille', name: 'Nous nous Battons pour notre Famille', hasValue: false, category: 'unité', definition: "Lorsqu'une unité alliée dotée du mot-clé Nous nous Battons pour notre Famille effectue une action Attaquer, après que l'effet a été résolu, choisissez une autre unité alliée dotée du mot-clé Nous nous Battons pour notre Famille à 2, si possible. L'unité choisie gagne 1 pion Esquive." },
  { id: 'observateur-x', name: 'Observateur X', hasValue: true, category: 'unité', definition: "En tant qu'action de carte, une unité dotée du mot-clé Observateur X peut choisir jusqu'à X unités alliées se trouvant à 2. Chaque unité choisie gagne un pion Viser." },
  { id: 'on-est-pas-des-regs', name: "On est pas des Regs", hasValue: false, category: 'unité', definition: "Une unité dotée du mot-clé On est pas des Regs ne peut pas dépenser de pions verts sur d'autres unités de soldats clones, et les autres unités de soldats clones ne peuvent pas dépenser les pions verts de cette unité. De plus, cette unité ne peut pas se faire prêter main-forte." },
  { id: 'operationnel-x', name: 'Opérationnel X', hasValue: true, category: 'unité', definition: "Après qu'une unité dotée du mot-clé Opérationnel X a effectué une action Attendre, elle gagne X pions Viser." },
  { id: 'ordre-direct', name: "Ordre Direct : Nom/Type d'Unité", hasValue: false, category: 'unité', definition: "Lors de chaque Phase de Commandement, pendant l'étape « Nommer des Commandants et donner des ordres », une unité dotée du mot-clé Ordre direct peut donner un ordre à une unité alliée à 2 portant le nom ou étant du type spécifié." },
  { id: 'pilotage-de-vehicule-x', name: 'Pilotage de Véhicule X', hasValue: true, category: 'unité', definition: "Quand une unité alliée à 3 d'une unité dotée du mot-clé Pilotage de Véhicule X vérifie si elle est paniquée, si les deux unités ont la même affiliation ou faction, l'unité alliée considère que l'unité dotée du mot-clé Pilotage de Véhicule X est une unité Commandement ayant une valeur de Commandement de X." },
  { id: 'pistolero', name: 'Pistolero', hasValue: false, category: 'unité', definition: "Lorsqu'une unité dotée du mot-clé Pistolero effectue son étape « Déclarer un défenseur supplémentaire », elle peut déclarer un défenseur supplémentaire et créer une réserve d'attaque consistant uniquement en une arme à distance qui a déjà été ajoutée à une autre réserve d'attaque. Le mot-clé Pistolero ne peut être utilisé qu'une fois par séquence d'attaque." },
  { id: 'pivot-complet', name: 'Pivot Complet', hasValue: false, category: 'unité', definition: "Lorsqu'une unité dotée du mot-clé Pivot Complet pivote, elle peut pivoter jusqu'à 360°." },
  { id: 'point-faible-x', name: 'Point Faible X : Avant/Arrière/Flancs', hasValue: true, category: 'unité', definition: "Tant qu'une unité dotée du mot-clé Point Faible X : avant/arrière/flancs défend, si le Chef de l'unité attaquante se trouve au moins partiellement dans l'arc de tir spécifié de l'unité en défense, la réserve d'attaque gagne le mot-clé Impact X, X étant alors égal à la valeur de Point Faible X. Tant qu'une unité dotée du mot-clé Point Faible X défend contre une attaque à distance effectuée par une arme à effet de zone, considérez le pion Charge ou Avantage comme étant le Chef de l'unité attaquante." },
  { id: 'position-preparee', name: 'Position Préparée', hasValue: false, category: 'unité', definition: "Pendant l'étape « Se déployer sur les positions préparées » de la mise en place, une unité dotée du mot-clé Position Préparée peut se déployer en plaçant son Chef d'unité intégralement en territoire allié. Ensuite, les figurines restantes de l'unité sont placées en cohésion avec leur Chef d'unité et intégralement en territoire allié. Cette unité gagne ensuite 1 pion Esquiver. Les figurines ne peuvent pas chevaucher un terrain infranchissable lorsqu'elles sont placées en utilisant Position Préparée." },
  { id: 'pouvoir-latent', name: 'Pouvoir Latent', hasValue: false, category: 'unité', definition: "À la fin de l'activation d'une unité dotée du mot-clé Pouvoir Latent, elle peut gagner 1 pion Suppression afin de lancer 1 dé de défense rouge. Dans ce cas, sur un résultat Adrénaline, choisissez une unité ennemie à 1 de cette figurine. L'unité choisie gagne 2 pions Suppression et 2 pions Immobilisation. Sur un résultat vierge, retirez 1 pion Blessure ou Poison d'une unité de soldats non-droïde alliée à 1 de cette figurine." },
  { id: 'precis-x', name: 'Précis X', hasValue: true, category: 'unité', definition: "Lorsqu'une unité attaquante dotée du mot-clé Précis X dépense un pion Viser pendant l'étape « Relancer les dés d'attaque », elle peut relancer jusqu'à X dés d'attaque supplémentaires par pion Viser dépensé." },
  { id: 'preste-x', name: 'Preste X', hasValue: true, category: 'unité', definition: "Le mot-clé Preste X permet à une unité de gagner X pions Esquive à chaque fois qu'elle effectue un déplacement normal au cours d'une action ou d'une action gratuite." },
  { id: 'prime', name: 'Prime', hasValue: false, category: 'unité', definition: "Pendant la mise en place, une unité dotée du mot-clé Prime choisit une unité Commandement ou Opérative ennemie : cette dernière gagne un pion Butin. Après qu'une unité alliée dotée du mot-clé Prime a vaincu, grâce à un effet ou une attaque, une unité ennemie dotée d'un ou plusieurs pions Prime, le contrôleur de l'unité alliée marque 1 PV." },
  { id: 'profil-bas', name: 'Profil Bas', hasValue: false, category: 'unité', definition: "Tant qu'elle défend contre une attaque à distance, si une unité dotée du mot-clé Profil Bas doit lancer un ou plusieurs dés de défense pendant l'étape « Lancer la réserve de couvert », elle lance un dé de défense de moins et ajoute à la place un résultat Critique supplémentaire à la réserve de couvert après le jet." },
  { id: 'programme', name: 'Programmé', hasValue: false, category: 'unité', definition: "Une unité dotée du mot-clé Programmé doit s'équiper d'au moins une carte Amélioration Force pendant la création d'armée." },
  { id: 'recharger-x', name: 'Recharger X', hasValue: true, category: 'unité', definition: "Lorsqu'une unité dotée du mot-clé Recharger X récupère, elle peut retourner jusqu'à X pions Bouclier inactifs sur leur côté actif." },
  { id: 'redeploiement', name: 'Redéploiement', hasValue: false, category: 'unité', definition: "Lorsqu'une unité dotée du mot-clé Redéploiement effectue un déplacement normal, elle peut effectuer un pivot avant ou après avoir effectué le déplacement normal." },
  { id: 'regenerer-x', name: 'Régénérer X', hasValue: true, category: 'unité', definition: "À la fin de l'activation d'une unité, si elle est dotée du mot-clé Régénérer X, elle lance un dé de défense blanc pour chaque pion Blessure qu'elle possède, pour un maximum de X pions. Pour chaque résultat Critique ou Adrénaline obtenu, elle retire un pion Blessure." },
  { id: 'renforts', name: 'Renforts', hasValue: false, category: 'unité', definition: "Au début de la Phase Finale du round 1 d'une partie, une unité dotée du mot-clé Renforts peut effectuer un déplacement gratuit à vitesse 1." },
  { id: 'retrait', name: 'Retrait', hasValue: false, category: 'unité', definition: "Tant qu'une unité de soldats dotée du mot-clé Retrait est engagée avec une seule unité ennemie, elle peut effectuer des déplacements normalement." },
  { id: 'riposte-graduee-x', name: 'Riposte Graduée X', hasValue: true, category: 'unité', definition: "Pendant la création d'armée, une unité dotée du mot-clé Riposte Graduée doit s'équiper de X améliorations." },
  { id: 'sans-entrave', name: 'Sans Entrave', hasValue: false, category: 'unité', definition: "Lorsqu'une unité dotée du mot-clé Sans Entrave effectue un déplacement, elle ne réduit pas sa vitesse maximale pour entrer dans un terrain difficile, en sortir ou le traverser." },
  { id: 'saut-x', name: 'Saut X', hasValue: true, category: 'unité', definition: "Une unité dotée du mot-clé Saut X peut effectuer l'action de carte Saut X à tout moment auquel elle peut effectuer une action Se déplacer. L'unité effectue une action Se déplacer normalement et peut ignorer le terrain ou mettre fin à ce déplacement sur un terrain de hauteur X ou moins. Tant qu'elle effectue un déplacement avec l'action accordée par Saut X, une unité ignore les effets des terrains difficiles et des autres figurines d'une hauteur inférieure ou égale à X. Lorsqu'elle effectue un déplacement avec l'action Saut X, une unité peut placer le gabarit de déplacement à cheval sur un terrain infranchissable mais ne peut pas terminer son déplacement sur ce terrain infranchissable. Lorsqu'une unité effectue l'action Saut X, mesurez la hauteur à partir de la position de départ de l'unité." },
  { id: 'sentinelle', name: 'Sentinelle', hasValue: false, category: 'unité', definition: "Une unité dotée du mot-clé Sentinelle peut dépenser un pion En attente après qu'une unité ennemie a effectué une attaque, un déplacement ou une action à 3 plutôt qu'à 2." },
  { id: 'specificite', name: 'Spécificité : Force Armée', hasValue: false, category: 'unité', definition: "Une unité dotée du mot-clé Spécificité ne peut être incluse que dans une armée utilisant la force armée spécifiée." },
  { id: 'speeder-x', name: 'Speeder X', hasValue: true, category: 'unité', definition: "Tant qu'elle se déplace, une unité dotée du mot-clé Speeder X peut se déplacer ou terminer son déplacement sur un terrain d'une hauteur inférieure ou égale à X. De plus, lorsqu'une unité ayant un socle avec encoches effectue un déplacement, elle saute l'étape 1 du déplacement des socles avec encoches, consistant à tourner le socle du Chef d'unité. Une unité dotée du mot-clé Speeder X doit effectuer une action Se déplacer obligatoire gratuite au début ou à la fin de son étape « Effectuer des actions ». Si une unité dotée du mot-clé Speeder X effectue plusieurs actions Se déplacer non obligatoires au cours de son activation, elle ne peut pas revendiquer de pions Atout au cours de cette activation. De plus, une unité dotée du mot-clé Speeder X qui a revendiqué un pion Atout ne peut effectuer qu'une seule action Se déplacer non obligatoire au cours de son activation." },
  { id: 'deplacement-obligatoire', name: 'Déplacement Obligatoire', hasValue: false, category: 'unité', definition: "Un déplacement obligatoire est une action Se déplacer gratuite (imposée par des mots-clés comme Mobile ou Speeder X). Pour l'effectuer, l'unité effectue un déplacement normal complet à sa vitesse maximale. Si elle ne peut pas, ou si un déplacement complet devait amener le socle de son Chef d'unité à se retrouver hors du champ de bataille, l'unité peut effectuer un déplacement partiel à la place, en terminant son déplacement le plus loin possible sur le gabarit de déplacement." },
  { id: 'stationnaire', name: 'Stationnaire', hasValue: false, category: 'unité', definition: "Une unité dotée du mot-clé Stationnaire ne peut pas effectuer de déplacements, sauf des pivots." },
  { id: 'stratege-x', name: 'Stratège X', hasValue: true, category: 'unité', definition: "Lorsqu'une unité utilise l'action Stratège X, elle gagne un pion Suppression, puis elle choisit X unités alliées à 2. Chaque unité choisie gagne un pion Viser et un pion Esquive." },
  { id: 'surcharge', name: 'Surcharge', hasValue: false, category: 'unité', definition: "Lorsqu'une unité alliée ayant le mot-clé IA débute son activation à 3 d'au moins 1 unité alliée dotée du mot-clé Surcharge, choisissez 1 de ces unités ayant Surcharge qui n'est pas paniquée. L'unité choisie peut gagner 1 pion Suppression. Dans ce cas, l'unité qui s'active ignore le mot-clé IA pendant son activation." },
  { id: 'surveillance-x', name: 'Surveillance X', hasValue: true, category: 'unité', definition: "En tant qu'action de carte ou action de carte gratuite, une unité dotée du mot-clé Surveillance X peut choisir une unité ennemie à 3 et en LdV. L'unité ennemie choisie gagne X pions Surveillance. Les pions Surveillance sont retirés pendant l'étape « Retirer les pions » de la Phase Finale. Pendant une attaque, une unité attaquante alliée peut dépenser n'importe quel nombre de pions Surveillance qui appartiennent à l'unité en défense au cours de l'étape « Relancer les dés d'attaque ». L'unité attaquante relance un dé d'attaque pour chaque pion Surveillance dépensé. Les pions Surveillance sont dépensés un par un, et un même dé peut être relancé plusieurs fois en dépensant des pions Surveillance ou Viser en conséquence. L'unité attaquante peut dépenser des pions Viser et Surveillance dans n'importe quel ordre." },
  { id: 'sustentation', name: 'Sustentation : Terrestre/Aérienne X', hasValue: true, category: 'unité', definition: "Une unité dotée du mot-clé Sustentation : terrestre X ou Sustentation : aérienne X peut effectuer des actions Attendre pendant l'étape « Effectuer des actions » et peut gagner et dépenser des pions En attente. Une unité dotée du mot-clé Sustentation : terrestre X ou Sustentation : aérienne X peut reculer. Une unité dotée du mot-clé Sustentation : terrestre X est considérée comme un véhicule terrestre par les autres unités pour vérifier la LdV. Pour tous les autres effets de jeu, l'unité reste considérée comme un véhicule à répulseurs. Une unité dotée du mot-clé Sustentation : aérienne X ignore le terrain de hauteur X ou moins lorsqu'elle se déplace et peut terminer un déplacement en chevauchant un tel terrain. Déraper : si l'unité a un socle avec encoches latérales, elle peut déraper grâce à une action Se déplacer. Déraper est un déplacement normal pour une figurine ayant un socle avec encoches et s'effectue comme tel, à l'exception des points suivants : pour un dérapage complet, au lieu de placer le gabarit dans l'encoche avant, placez-le dans une des encoches latérales, puis déplacez la figurine et placez son encoche latérale opposée à l'autre extrémité du gabarit. Pour un dérapage partiel, placez de même le gabarit dans une encoche latérale au début du déplacement ; à la fin, la figurine doit être placée de telle sorte que la ligne reliant ses deux encoches latérales soit parallèle à la section du gabarit atteinte. Lorsqu'elle dérape, une unité réduit de 1 sa vitesse, jusqu'à un minimum de 1." },
  { id: 'tacticien-x', name: 'Tacticien X', hasValue: true, category: 'unité', definition: "Le mot-clé Tacticien X permet à une unité de gagner un nombre de pions Viser égal à X chaque fois qu'elle effectue un déplacement normal lors d'une action ou d'une action gratuite." },
  { id: 'telle-est-la-voie', name: 'Telle est la Voie', hasValue: false, category: 'unité', definition: "Lorsqu'une unité alliée dotée du mot-clé Telle est la Voie reçoit un ordre, choisissez jusqu'à X autres unités alliées à 2 d'elle. Chaque unité choisie effectue, en tant qu'action gratuite, l'action indiquée par le mot-clé Telle est la Voie de l'unité ayant reçu un ordre." },
  { id: 'tenir-bon', name: 'Tenir Bon', hasValue: false, category: 'unité', definition: "Tant qu'une unité dotée du mot-clé Tenir Bon est engagée, elle gagne Critique : Succès et Adrénaline : Dodge." },
  { id: 'tenir-le-cap', name: 'Tenir le Cap : Mot-clé', hasValue: false, category: 'unité', definition: "Tant qu'une unité dotée du mot-clé Tenir le Cap a son Chef d'unité à 7 de 1 ou plusieurs pions Objectif ou détient 1 ou plusieurs pions Objectif, elle a le mot-clé indiqué." },
  { id: 'tentation', name: 'Tentation', hasValue: false, category: 'unité', definition: "Si une unité alliée est vaincue par une attaque ennemie et que l'unité attaquante se trouve à 3 d'une unité dotée du mot-clé Tentation, une fois que l'attaque est résolue, cette unité dotée du mot-clé Tentation peut effectuer une action Attaquer gratuite ou un déplacement à vitesse 2 en ignorant le terrain difficile. Une unité ne peut utiliser le mot-clé Tentation qu'une fois par round." },
  { id: 'tirer-les-ficelles', name: 'Tirer les Ficelles', hasValue: false, category: 'unité', definition: "Lorsqu'une unité utilise l'action de carte Tirer les Ficelles, choisissez une autre unité de soldats alliée à 2. L'unité choisie peut effectuer une action de carte gratuite ou une action Se déplacer gratuite." },
  { id: 'tireur-delite-x', name: "Tireur d'Élite X", hasValue: true, category: 'unité', definition: "Pendant l'étape « Déterminer le couvert », une unité dotée du mot-clé Tireur d'Élite X soustrait X de la valeur numérique du couvert du défenseur. Par exemple, une unité bénéficiant d'un couvert lourd et d'un pion Suppression qui est attaquée par une unité dotée de Tireur d'Élite 1 bénéficie d'un couvert léger." },
  { id: 'tireur-embusque', name: 'Tireur Embusqué', hasValue: false, category: 'unité', definition: "Après avoir converti les adrénalines d'attaque au cours de l'étape « Convertir les adrénalines d'attaque », une unité dotée du mot-clé Tireur Embusqué peut dépenser n'importe quel nombre de pions Viser. Pour chaque pion Viser ainsi dépensé, au lieu de relancer les dés, transformez un résultat vierge en résultat Succès ou un résultat Succès en résultat Critique, ou bien dépensez deux pions Viser pour transformer un résultat vierge en résultat Critique." },
  { id: 'tirs-de-soutien', name: 'Tirs de Soutien', hasValue: false, category: 'unité', definition: "Après qu'une unité dotée du mot-clé Tirs de Soutien a reçu un ordre, elle gagne un pion En attente." },
  { id: 'transport', name: 'Transport', hasValue: false, category: 'unité', definition: "Pendant la mise en place, une unité dotée du mot-clé Transport peut choisir une unité de soldats alliée à transporter. Pendant l'étape « Nommer des Commandants et donner des ordres » de la Phase de Commandement du round 1, une unité dotée du mot-clé Transport peut donner un ordre à l'unité choisie. Si l'unité choisie n'est pas déployée lorsque l'unité dotée du mot-clé Transport se déploie, une fois que l'effet est résolu, l'unité choisie se déploie en effectuant un déplacement à vitesse 1. Commencez à mesurer le déplacement en plaçant les deux pointes d'une extrémité du gabarit de déplacement de façon qu'elles touchent toutes deux le socle de l'unité dotée du mot-clé Transport. Lorsque l'unité choisie se déploie de cette manière, le Chef de cette unité mesure la distance verticale parcourue pendant ce déplacement en partant de l'unité dotée du mot-clé Transport." },
  { id: 'traque', name: 'Traqué', hasValue: false, category: 'unité', definition: "Pendant la mise en place, si une ou plusieurs unités ennemies sont dotées du mot-clé Prime, chaque unité dotée du mot-clé Traqué gagne un pion Prime." },
  { id: 'travail-dequipe', name: "Travail d'Équipe : Nom d'Unité", hasValue: false, category: 'unité', definition: "Lorsqu'une unité dotée du mot-clé Travail d'Équipe se trouve à 2 d'une unité alliée portant le nom spécifié par le mot-clé Travail d'Équipe, si l'une ou l'autre des unités gagne un pion Viser ou Esquive, l'autre unité gagne un pion du même type." },
  { id: 'vehicule-grimpant', name: 'Véhicule Grimpant', hasValue: false, category: 'unité', definition: "Une unité dotée du mot-clé Véhicule Grimpant est considérée comme une unité de soldats lorsqu'elle grimpe." },
  { id: 'vivacite-desprit', name: "Vivacité d'Esprit", hasValue: false, category: 'unité', definition: "Lorsqu'une unité effectue l'action de carte Vivacité d'esprit, elle gagne 1 pion Viser et 1 pion Esquive." },
];

const WEAPON_KEYWORDS: KeywordDef[] = [
  { id: 'anti-materiel-x', name: 'Anti-matériel X', hasValue: true, category: 'arme', definition: "Lorsqu'une unité défend contre une attaque dont la réserve d'attaque est dotée du mot-clé Anti-matériel X, si l'unité en défense est une unité de Véhicule, améliorez X des dés d'attaque de cette arme." },
  { id: 'anti-personnel-x', name: 'Anti-personnel X', hasValue: true, category: 'arme', definition: "Lorsqu'une unité défend contre une attaque dont la réserve d'attaque est dotée du mot-clé Anti-personnel X, si l'unité en défense est une unité de soldats, améliorez X des dés d'attaque de cette arme." },
  { id: 'arme-a-effet-de-zone', name: 'Arme à Effet de Zone', hasValue: false, category: 'arme', definition: "Une arme affichant une icône de portée jaune est une arme à effet de zone. Lorsque vous utilisez une arme à effet de zone, effectuez une attaque distincte contre chaque unité, alliée et ennemie, qui se trouve en LdV et à la portée indiquée par le chiffre figurant sur l'icône de portée, même si cette unité est engagée. Les attaques effectuées par des armes à effet de zone sont toujours des attaques à distance. Les armes à effet de zone ne peuvent jamais être incluses dans une réserve d'attaque constituée par une unité et doivent toujours être la seule arme d'une réserve d'attaque." },
  { id: 'armer-x', name: 'Armer X : Type de Charge', hasValue: true, category: 'arme', definition: "Une unité équipée d'une carte dotée du mot-clé Armer X : type de charge peut effectuer l'action Armer X. Lorsqu'une unité effectue l'action Armer X, l'unité place X pions Charge (Avantage) du type spécifié et correspondant à la couleur du joueur qui la contrôle intégralement à 1 et en LdV de son Chef d'unité. Les pions Charge ne peuvent pas chevaucher les pions Objectif et Avantage, ni d'autres pions Charge, et ils doivent être placés complètement à plat sur une surface plane." },
  { id: 'assaut-x', name: 'Assaut X', hasValue: true, category: 'arme', definition: "Lorsqu'une arme dotée du mot-clé Assaut X est ajoutée à une réserve d'attaque, si l'unité en défense est à 1 du Chef de l'unité attaquante, vous pouvez améliorer X dés d'attaque de cette arme." },
  { id: 'autodestruction-x-arme', name: 'Autodestruction X (arme)', hasValue: true, category: 'arme', definition: "Une arme affichant une icône rouge est une arme autodestructrice, qui ne peut être utilisée que pendant les attaques autodestructrices. Ces dernières sont des attaques à distance même si les armes autodestructrices ne sont pas des armes à distance. Une unité peut effectuer une attaque autodestructrice en tant qu'action gratuite pendant son activation si elle possède au moins X pions Blessure. Effectuez une attaque en utilisant l'arme autodestructrice d'une unité contre chaque unité à 1 et en LdV, même celles qui sont engagées. Les attaques autodestructrices ne peuvent pas être effectuées par une unité embarquée sur un transport. Après avoir effectué toutes les attaques, l'unité effectuant l'attaque autodestructrice est vaincue et retirée de la partie." },
  { id: 'belier-x', name: 'Bélier X', hasValue: true, category: 'arme', definition: "Tant qu'une unité effectue une attaque en utilisant une réserve d'attaque qui contient une arme dotée du mot-clé Bélier X, pendant l'étape « Modifier les dés d'attaque », elle peut changer X résultats en résultats Critique si elle remplit l'une ou l'autre des conditions suivantes : le Chef de l'unité a un socle avec encoches et l'unité a effectué au moins un déplacement normal complet à sa vitesse maximale pendant la même activation qu'une attaque utilisant Bélier X ; ou le Chef de l'unité a un petit socle et l'unité a effectué au moins un déplacement pendant la même activation qu'une attaque utilisant Bélier X." },
  { id: 'bordee-x', name: 'Bordée X', hasValue: true, category: 'arme', definition: "Une unité affichant une icône de portée « 8 » est une arme de bordée et ne peut être utilisée que lors d'une attaque de bordée. Les attaques de bordée ne sont ni des attaques à distance ni des attaques au corps-à-corps. Une unité peut effectuer X attaques de bordée pendant son activation. Une unité possédant une arme de bordée peut effectuer une attaque de bordée après avoir effectué un déplacement normal durant lequel le gabarit de déplacement ou le socle d'au moins une de ses figurines a chevauché le socle d'une figurine ennemie. Après avoir terminé le déplacement, l'unité possédant l'arme de bordée effectue une attaque contre l'unité à travers laquelle elle s'est déplacée, en ignorant la portée pour cette attaque. Elle ne peut constituer qu'une seule réserve d'attaque lorsqu'elle effectue cette attaque et seules des armes dotées du mot-clé Bordée X peuvent être ajoutées à cette réserve d'attaque. L'arme de bordée n'est ajoutée qu'une seule fois à la réserve d'attaque, même si l'unité contient plusieurs figurines. Si une unité peut effectuer plusieurs attaques de bordée pendant son activation, elle doit effectuer un déplacement distinct à travers une unité ennemie pour chaque attaque de bordée." },
  { id: 'cable-de-remorquage', name: 'Câble de Remorquage', hasValue: false, category: 'arme', definition: "Après qu'un véhicule a été blessé par une réserve d'attaque qui contient une arme dotée du mot-clé Câble de Remorquage, le joueur qui a effectué l'attaque effectue un pivot avec le véhicule qui a été blessé, puis il gagne 1 pion Immobilisation." },
  { id: 'critique-x', name: 'Critique X', hasValue: true, category: 'arme', definition: "Lorsqu'une unité convertit des adrénalines d'attaque pour une réserve d'attaque dotée du mot-clé Critique X, pendant l'étape « Convertir les adrénalines d'attaque », elle peut convertir jusqu'à X résultats Succès en résultats Critique." },
  { id: 'debordement', name: 'Débordement', hasValue: false, category: 'arme', definition: "Lorsqu'une unité effectue une attaque dont la réserve contient au moins 1 arme dotée du mot-clé Débordement, si elle dépense au moins 1 pion Viser pendant l'étape « Relancer les dés d'attaque », l'unité en défense gagnera 1 pion Suppression lors de l'étape « Attribuer un pion Suppression au défenseur »." },
  { id: 'deflagration', name: 'Déflagration', hasValue: false, category: 'arme', definition: "Pendant l'étape « Appliquer le couvert », une unité en défense ne peut pas bénéficier de couvert léger ni de couvert lourd pour annuler des résultats Succès obtenus par une réserve d'attaque qui contient des dés ajoutés par une arme dotée du mot-clé Déflagration." },
  { id: 'dispersion', name: 'Dispersion', hasValue: false, category: 'arme', definition: "Après qu'une unité a effectué une attaque contre une unité de soldats ayant des petits socles et utilisant une réserve d'attaque qui contient une arme dotée du mot-clé Dispersion, cette unité peut placer toute figurine de l'unité en défense autre que le Chef d'unité, en respectant les règles de cohésion, comme si le Chef de l'unité en défense venait d'effectuer un déplacement normal." },
  { id: 'encombrant', name: 'Encombrant', hasValue: false, category: 'arme', definition: "Lorsqu'une unité ajoute une arme dotée du mot-clé Encombrant à une réserve d'attaque, elle dégrade chacun des dés d'attaque de cette arme si cette unité a effectué un déplacement pendant la même activation." },
  { id: 'equipe-sniper', name: 'Équipe Sniper', hasValue: false, category: 'arme', definition: "Lorsqu'une unité effectue une attaque lors de son activation, si une de ses réserves d'attaque ne contient que des armes dotées du mot-clé Équipe Sniper, améliorez chaque dé d'attaque de ces armes si les conditions suivantes sont vraies : l'unité n'a pas effectué de déplacement pendant son activation, et chacune de ses figurines a une LdV vers 1 ou plusieurs figurines de l'unité en défense. Si vous avez ainsi amélioré des dés, après l'étape « Convertir les adrénalines d'attaque » de cette réserve d'attaque, vous pouvez annuler tous les dés d'attaque de cette réserve d'attaque et passer directement à l'étape « Attribuer un pion Suppression au défenseur ». Dans ce cas, si au moins 1 résultat Critique a été annulé, l'unité en défense subit 1 blessure." },
  { id: 'explosion-x', name: 'Explosion X : Type de Charge', hasValue: true, category: 'arme', definition: "Après qu'une unité contrôlée par n'importe quel joueur a attaqué, s'est déplacée ou a effectué une action, chaque unité possédant une arme dotée du mot-clé Explosion X peut faire exploser jusqu'à X pions Charge (Avantage) alliés du type spécifié. Lorsqu'un pion doit exploser, il explose avant toute autre capacité ou tout autre effet qui se déclenche après qu'une unité s'est déplacée ou a effectué une action, sauf en cas de dépense d'un pion En attente, qui peut être dépensé par une unité avant que le pion n'explose. Si les deux joueurs possèdent des unités qui peuvent faire exploser des pions Charge, le joueur qui ne contrôle pas l'unité venant d'effectuer l'attaque, le déplacement ou l'action peut utiliser le mot-clé Explosion X de son unité le premier. Lorsqu'un pion explose, effectuez une attaque distincte contre chaque unité, alliée et ennemie, qui a une LdV sur le pion et se trouve à portée de l'arme à effet de zone, en utilisant la fenêtre de conversion d'adrénaline et les mots-clés d'arme de la carte correspondant au pion qui explose. Le pion qui explose est considéré comme l'unité attaquante lorsqu'il effectue des attaques, ce qui signifie que le joueur ne peut pas dépenser de pions Viser, ni modifier les dés d'attaque, quelles que soient les capacités de l'unité qui a placé le pion. Une fois qu'un pion a explosé, retirez-le du champ de bataille." },
  { id: 'fixe', name: 'Fixe : Avant/Arrière/Flancs', hasValue: false, category: 'arme', definition: "Pour ajouter une arme dotée du mot-clé Fixe : avant/arrière/flancs à une réserve d'attaque, l'unité en défense doit comprendre au moins une figurine dont le socle se trouve partiellement à l'intérieur de l'arc de tir spécifié de la figurine attaquante." },
  { id: 'haute-velocite', name: 'Haute Vélocité', hasValue: false, category: 'arme', definition: "Tant qu'elle défend contre une attaque dont la réserve d'attaque ne contient que des armes dotées du mot-clé d'arme Haute Vélocité, l'unité en défense ne peut pas dépenser de pions Esquive pendant l'étape « Appliquer les esquives et couverts »." },
  { id: 'immobiliser-x', name: 'Immobiliser X', hasValue: true, category: 'arme', definition: "Une unité qui subit une ou plusieurs blessures après avoir défendu contre une attaque qui comprend une arme dotée du mot-clé d'arme Immobiliser X gagne X pions Immobilisation. La vitesse maximale d'une unité est réduite de 1 pour chaque pion Immobilisation qu'elle possède. Une unité dont la vitesse maximale est 0 et qui possède au moins un pion Immobilisation ne peut pas effectuer de déplacements (quel qu'en soit le type). À la fin de l'activation d'une unité, elle retire tout pion Immobilisation qu'elle possède. Lorsqu'une unité se déplace, appliquez tout effet qui augmente sa vitesse maximale avant d'appliquer les effets qui réduisent la vitesse maximale de cette unité." },
  { id: 'immunite-deflexion', name: 'Immunité : Déflexion', hasValue: false, category: 'arme', definition: "Pendant une attaque, si la réserve d'attaque contient des armes dotées du mot-clé Immunité : déflexion, l'unité attaquante ne peut pas subir de blessures dues au mot-clé Déflexion." },
  { id: 'impact-x', name: 'Impact X', hasValue: true, category: 'arme', definition: "Pendant l'étape « Modifier les dés d'attaque », si l'unité en défense est dotée du mot-clé Armure ou Armure X, une unité dont la réserve d'attaque contient une arme dotée du mot-clé Impact X peut changer jusqu'à X résultats Succès en résultats Critique pour cette attaque." },
  { id: 'ion-x', name: 'Ion X', hasValue: true, category: 'arme', definition: "Une unité de véhicule ou de soldats droïdes qui subit des blessures après avoir défendu contre une attaque comprenant une arme dotée du mot-clé Ion X gagne X pions Ionique. Au début de l'activation d'une unité, lancez un dé de défense blanc pour chaque pion Ionique que possède l'unité. Si vous obtenez des résultats vierges, cette unité effectue une action de moins pendant son activation. À la fin de l'activation d'une unité, elle retire tout pion Ionique qu'elle possède. Si une réserve d'attaque est dotée du mot-clé Ion X, au début de l'étape « Modifier les dés d'attaque » de la séquence d'attaque, avant tout autre effet, l'unité en défense doit retourner des pions Bouclier actifs, si possible, pour chaque résultat Succès et Critique du jet d'attaque, jusqu'à X." },
  { id: 'letal-x', name: 'Létal X', hasValue: true, category: 'arme', definition: "Lorsqu'une unité effectue une attaque dont la réserve contient une arme dotée du mot-clé Létal X, elle peut dépenser jusqu'à X pions Viser pendant l'étape « Modifier les dés d'attaque ». Dans ce cas, la réserve d'attaque gagne Perforant 1 pour chaque pion Viser dépensé. L'unité attaquante ne peut pas relancer de dés grâce aux pions Viser ainsi dépensés." },
  { id: 'longue-distance', name: 'Longue Distance', hasValue: false, category: 'arme', definition: "Lorsqu'une unité possédant au moins une arme dotée du mot-clé Longue Distance effectue une attaque, avant de choisir une unité ennemie à attaquer pendant l'étape « Déclarer le défenseur », cette unité peut dépenser un pion Viser pour améliorer de 1 la portée maximale de chaque arme ayant Longue Distance jusqu'à la fin de la séquence d'attaque. L'unité attaquante ne peut pas relancer de dés grâce aux pions Viser ainsi dépensés. Un seul pion Viser peut être ainsi dépensé par séquence d'attaque." },
  { id: 'perforant-x', name: 'Perforant X', hasValue: true, category: 'arme', definition: "Si une unité attaque avec une arme dotée du mot-clé Perforant X, elle peut annuler jusqu'à X résultats Critique pendant l'étape « Modifier les dés de défense ». Le mot-clé Perforant X peut être utilisé pour annuler des résultats Critique de dés de défense lancés par une unité utilisant le mot-clé Gardien X. Dans ce cas, traitez les résultats Critique annulés comme des résultats vierges. Après avoir utilisé le mot-clé Perforant X de cette manière, toute valeur inutilisée de Perforant X peut toujours être utilisée pour annuler des résultats Critique obtenus par le défenseur. Par exemple, une unité dotée du mot-clé Perforant 3 attaque une unité ennemie, et une autre unité ennemie utilise Gardien 2 pour annuler 2 résultats Succès. Après avoir converti les résultats Adrénaline, l'unité utilisant le mot-clé Gardien a obtenu 2 résultats Critique. L'unité attaquante utilise Perforant pour annuler les 2 résultats Critique et l'unité utilisant Gardien subit 2 blessures. Le défenseur lance alors les dés de défense et l'unité attaquante peut annuler 1 résultat Critique de plus obtenu par le défenseur puisqu'elle n'a utilisé que 2 points sur les 3 accordés par son mot-clé Perforant 3." },
  { id: 'poison-x', name: 'Poison X', hasValue: true, category: 'arme', definition: "Une unité de soldats non-droïdes qui subit des blessures provoquées par une réserve d'attaque contenant une arme dotée du mot-clé Poison X gagne X pions Poison. À la fin de l'activation d'une unité, elle subit une blessure pour chaque pion Poison qu'elle possède, puis elle retire tous ses pions Poison." },
  { id: 'polyvalent', name: 'Polyvalent', hasValue: false, category: 'arme', definition: "Certaines armes à distance sont dotées du mot-clé Polyvalent. Une unité peut effectuer une attaque à distance en utilisant une arme dotée du mot-clé Polyvalent même si elle est engagée. Une arme dotée du mot-clé Polyvalent qui est à la fois une arme de corps-à-corps et à distance peut être utilisée pour effectuer soit une attaque au corps-à-corps soit une attaque à distance." },
  { id: 'primitif', name: 'Primitif', hasValue: false, category: 'arme', definition: "Pendant l'étape « Modifier les dés d'attaque », après avoir résolu tous les points du mot-clé Impact X, si l'unité en défense est dotée du mot-clé Armure ou Armure X, une unité dont la réserve d'attaque contient une arme dotée du mot-clé Primitif doit changer tous ses résultats Critique en résultats Succès pour cette attaque." },
  { id: 'rayons-x', name: 'Rayons X', hasValue: true, category: 'arme', definition: "Pendant l'étape « Déclarer un défenseur supplémentaire », si la réserve d'attaque d'une unité contient une arme dotée du mot-clé Rayons X, cette unité peut déclarer jusqu'à X attaques supplémentaires en constituant des réserves d'attaque n'utilisant que l'arme dotée de Rayons X, même si l'arme a déjà été ajoutée à une réserve d'attaque. Ces attaques supplémentaires ne génèrent pas d'autres attaques. Chaque attaque supplémentaire doit cibler une unité en défense différente qui se trouve à 1 de la dernière unité déclarée en défense. Ces attaques supplémentaires doivent être en LdV de l'unité attaquante mais peuvent se trouver au-delà de la portée maximale de l'arme dotée du mot-clé Rayons X. Les unités ne peuvent pas utiliser les mots-clés Rayons X et Pistolero au cours de la même attaque." },
  { id: 'souffle', name: 'Souffle', hasValue: false, category: 'arme', definition: "Lorsqu'une figurine ajoute une arme dotée du mot-clé Souffle à la réserve d'attaque, cette arme fait contribuer ses dés un nombre de fois égal au nombre de figurines de l'unité en défense qui sont en LdV de la figurine utilisant cette arme. Par exemple, si un AT-ST attaque une unité de 3 Death Troopers avec un lance-flamme, comme le lance-flamme est doté du mot-clé Souffle et dispose de 2 dés noirs, le lance-flamme ajoute 6 dés d'attaque noirs à la réserve d'attaque." },
  { id: 'suppressif', name: 'Suppressif', hasValue: false, category: 'arme', definition: "Après avoir défendu contre une réserve d'attaque qui contient une arme dotée du mot-clé Suppressif, l'unité en défense gagne un pion Suppression pendant l'étape « Attribuer un pion Suppression au défenseur »." },
];

const CARD_KEYWORDS: KeywordDef[] = [
  { id: 'arme-de-poing', name: 'Arme de Poing : Corps-à-Corps/à Distance', hasValue: false, category: 'carte', definition: "Si une amélioration qui ajoute une figurine à une unité est dotée du mot-clé Arme de Poing : corps-à-corps, la figurine ajoutée par cette amélioration ne peut pas ajouter à une réserve d'attaque des armes de corps-à-corps autres que celles indiquées sur la carte Amélioration dotée du mot-clé Arme de Poing : corps-à-corps. Si une amélioration qui ajoute une figurine à une unité est dotée du mot-clé Arme de Poing : à distance, la figurine ajoutée par cette amélioration ne peut pas ajouter à une réserve d'attaque des armes à distance autres que celles indiquées sur la carte Amélioration dotée du mot-clé Arme de Poing : à distance. Par exemple, la carte Amélioration « Garde avec Bâton Statique » fournit une arme de corps-à-corps et le mot-clé Arme de Poing : corps-à-corps. La figurine ajoutée par cette amélioration ne peut utiliser que l'arme indiquée sur l'amélioration « Garde avec Bâton Statique » pendant une attaque au corps-à-corps. Cette figurine peut toujours utiliser n'importe quelle arme à distance disponible, telle que l'arme à distance indiquée sur la carte Unité « Gardes Royaux de l'Empereur », pendant une attaque à distance." },
  { id: 'chef', name: 'Chef', hasValue: false, category: 'carte', definition: "Une figurine dotée du mot-clé Chef est considérée comme le Chef d'une unité pour tous les effets de jeu et capacités. Si une figurine dotée du mot-clé Chef ayant un seuil de blessure de 2 est vaincue alors qu'elle se trouve dans une unité ayant un seuil de blessure de 1, remplacez normalement une des figurines restantes de cette unité, puis attribuez un pion Blessure à la figurine dotée du mot-clé Chef. Chaque unité ne peut s'équiper que d'une seule carte Amélioration dotée du mot-clé Chef." },
  { id: 'cycle', name: 'Cycle', hasValue: false, category: 'carte', definition: "À la fin de l'activation d'une unité, redressez chacune de ses cartes Amélioration inclinées dotées du mot-clé Cycle qui n'a pas été utilisée pendant cette activation. Seule l'utilisation de l'arme, des mots-clés ou d'un autre texte de la carte est considérée comme utiliser cette carte Amélioration." },
  { id: 'divulgation', name: 'Divulgation', hasValue: false, category: 'carte', definition: "Certaines cartes Commandement sont dotées du mot-clé Divulgation : elles sont alors divisées par une ligne horizontale, qui sert à séparer visuellement l'effet du mot-clé Divulgation de l'effet normal de la carte Commandement. Certaines de ces cartes Commandement disposent de plusieurs options : le joueur doit alors en choisir une. Ces cartes peuvent être révélées au début de la phase ou étape indiquée par le mot-clé Divulgation. Si une carte est révélée de cette manière, résolvez le texte qui suit le mot-clé Divulgation. Une carte ainsi révélée n'est pas jouée : elle est remise dans la main de Commandement de ce joueur à la fin de l'étape au cours de laquelle elle a été divulguée. Si une carte qui a le mot-clé Permanent est divulguée, elle n'est pas remise dans la main de Commandement, mais reste en jeu. Les joueurs peuvent divulguer autant de cartes Commandement qu'ils le souhaitent. Si les deux joueurs disposent de cartes Commandement qui doivent être divulguées en même temps, le joueur bleu peut révéler la sienne le premier. S'il décline cette opportunité, la carte ne peut plus être divulguée." },
  { id: 'non-combattant', name: 'Non-combattant', hasValue: false, category: 'carte', definition: "Une figurine dotée du mot-clé Non-combattant ne peut pas ajouter d'armes aux réserves d'attaque, et les blessures doivent être attribuées à des figurines autres que des Chefs d'unité n'étant pas dotées du mot-clé Non-combattant, si possible. Si une figurine dotée du mot-clé Non-combattant possède déjà un ou plusieurs pions Blessure, elle doit se voir attribuer des blessures avant les figurines qui ne possèdent pas de pions Blessure. Si la figurine de Chef d'unité d'une unité dotée du mot-clé Non-combattant est vaincue, une figurine Non-combattante ne peut pas être remplacée par une nouvelle figurine de Chef d'unité sauf s'il n'y a pas d'autres figurines n'étant pas dotées du mot-clé Non-combattant." },
  { id: 'permanent', name: 'Permanent', hasValue: false, category: 'carte', definition: "Certaines cartes Commandement sont dotées du mot-clé Permanent. Contrairement aux cartes Commandement ordinaires, ces cartes ne sont pas défaussées pendant la Phase Finale et leurs effets persistent tant qu'elles sont en jeu." },
  { id: 'petit', name: 'Petit', hasValue: false, category: 'carte', definition: "Une unité comprenant 1 ou plusieurs figurines Alter Ego dotées du mot-clé Petit ne peut pas être ciblée par des attaques si le Chef de l'unité attaquante n'a une LdV que vers la figurine Alter Ego dotée du mot-clé Petit." },
  { id: 'pions-bane', name: 'Pions Bane (Cad Bane)', hasValue: false, category: 'carte', definition: "Cad Bane dispose de trois pions Bane uniques qu'il peut placer sur le champ de bataille. Les pions Bane sont recto verso : un côté uniformisé (face cachée) et un côté comportant une image parmi trois différentes, chacune déclenchant un effet unique (face visible). Les pions Bane doivent être placés face cachée sur le champ de bataille et ils ne peuvent pas chevaucher de pions Objectif et Avantage. Les pions Bane sont des effets ennemis et chaque joueur ne peut posséder qu'un exemplaire de chaque pion Bane sur le champ de bataille à la fois. Lorsqu'une figurine ennemie se déplace, se déploie ou est placée à 1 d'un pion Bane ennemi, si cette figurine a une LdV vers le pion, ce dernier est révélé. Les figurines peuvent se déplacer à travers les pions Bane, mais pas les chevaucher. Lorsqu'un pion Bane est révélé, il a l'un des effets suivants : « Me voilà » : si Cad Bane ne se trouve pas sur le champ de bataille et n'est pas vaincu, son pion Me voilà est remplacé par sa figurine, qui se donne alors un ordre à elle-même ; si Cad Bane se trouve déjà sur le champ de bataille, le pion est simplement remplacé par sa figurine (tout pion qui lui était attribué le reste) ; si Cad Bane est vaincu, retirez ce pion. Au début de chaque round, en commençant par le joueur bleu, un joueur peut révéler un pion Me voilà allié et résoudre ses effets. « Fumée et miroir » : le pion est retiré. « Kablamo ! » : le pion explose en utilisant le profil d'arme indiqué sur la carte Commandement de Cad Bane « Je Fixe les Règles à Présent ». Ensuite, le pion est retiré." },
  { id: 'pions-graffiti', name: 'Pions Graffiti', hasValue: false, category: 'carte', definition: "Un pion Graffiti (Avantage) représente une image ou un signe au fort pouvoir symbolique tagué sur le terrain du champ de bataille. Les pions Graffiti ont un effet sur le moral d'une unité, ils sont recto verso et doivent être placés à plat avec comme face visible la couleur correspondant au joueur les contrôlant. Pendant l'étape « Se rallier » de l'activation d'une unité, elle peut lancer un dé supplémentaire si elle a une LdV vers et se trouve à 2 d'un pion Graffiti placé par une figurine alliée. Elle doit lancer un dé de moins (jusqu'à un minimum de 1 dé) si elle a une LdV et se trouve à 2 d'un pion Graffiti placé par une figurine ennemie. Les pions Graffiti restent en jeu jusqu'à la fin de la partie. Les unités peuvent se déplacer au travers des pions Graffiti et terminer leurs déplacements en chevauchant ces derniers." },
  { id: 'reconfiguration', name: 'Reconfiguration', hasValue: false, category: 'carte', definition: "Lorsqu'une unité équipée d'une carte Amélioration dotée du mot-clé Reconfiguration récupère ou effectue une action Récupérer, le joueur qui contrôle cette unité peut retourner cette carte Amélioration sur son autre face en plus de tout effet lié à la récupération. Si une carte Amélioration affiche l'icône Incliner, utiliser la capacité Reconfiguration ne provoque pas l'inclinaison de cette carte Amélioration." },
  { id: 'reparation-x', name: 'Réparation X : Capacité Y', hasValue: true, category: 'carte', definition: "Lorsqu'une unité utilise l'action de carte Réparation X : Capacité Y, choisissez une unité de soldats droïdes ou de véhicule alliée à 1 et en LdV et placez un pion Blessure sur la carte dotée du mot-clé Réparation X : Capacité Y. Retirez au total jusqu'à X pions Blessure, Ionique et/ou Dégât de véhicule de l'unité choisie ou restaurez jusqu'à X figurines de cette unité. Cette capacité ne peut pas être utilisée si la carte dotée du mot-clé Réparation X : Capacité Y possède sur elle un nombre de pions Blessure supérieur ou égal à Y. Les pions Blessure placés sur des cartes ne sont pas considérés comme possédés par des unités et ne comptent pas dans le seuil de blessure de cette unité. Ils ne peuvent pas non plus être retirés par des capacités qui retirent des pions Blessure à des unités. Si une unité dispose de plusieurs capacités Réparation X : Capacité Y, considérez chaque mot-clé comme une capacité à part. De plus, chaque action est considérée comme unique, et une unité qui a accès à plusieurs d'entre elles ne peut utiliser chaque capacité qu'une seule fois au cours de son activation. Cette règle s'applique même si l'unité a accès à deux capacités identiques de différentes sources." },
  { id: 'restauration', name: 'Restauration', hasValue: false, category: 'carte', definition: "Certaines capacités, comme les mots-clés Traiter et Réparation, de même que certains effets de carte, permettent à un joueur de restaurer des figurines dans des unités alliées. Pour restaurer une figurine dans une unité, une ou plusieurs figurines de cette unité doivent avoir été vaincues ce round. Choisissez une figurine qui a été vaincue pendant le round en cours et placez cette figurine sur le champ de bataille en cohésion avec son Chef d'unité. Ensuite, donnez à cette figurine un nombre de pions Blessure égal au seuil de blessure indiqué sur sa carte Unité ou Amélioration moins un." },
  { id: 'traiter-x', name: 'Traiter X : Capacité Y', hasValue: true, category: 'carte', definition: "Lorsqu'une unité utilise l'action de carte Traiter X : Capacité Y, choisissez une unité de soldats non-droïdes alliée à 1 et en LdV et placez un pion Blessure sur la carte dotée du mot-clé Traiter X : Capacité Y. Retirez au total jusqu'à X pions Blessure et/ou Poison de l'unité choisie ou restaurez jusqu'à X figurines dans cette unité. Cette capacité ne peut pas être utilisée si la carte dotée du mot-clé Traiter X : Capacité Y possède sur elle un nombre de pions Blessure supérieur ou égal à Y. Les pions Blessure placés sur des cartes ne sont pas considérés comme possédés par des unités et ne comptent pas dans le seuil de blessure de cette unité. Ils ne peuvent pas non plus être retirés par des capacités qui retirent des pions Blessure à des unités. Si une unité dispose de plusieurs capacités Traiter X : Capacité Y, considérez chaque mot-clé comme une capacité à part. De plus, chaque action est considérée comme unique, et une unité qui a accès à plusieurs d'entre elles ne peut utiliser chaque capacité qu'une seule fois au cours de son activation. Cette règle s'applique même si l'unité a accès à deux capacités identiques de différentes sources." },
];

